import{_ as r,C as n,o as l,c as o,j as i,E as e,a as t,a2 as d}from"./chunks/framework.C21TwvGF.js";const v=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/9-sinf/"},"n":2,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":4,"title":"Foydalanuvchi ssenariysi, User Flow va Customer Journey Map (CJM)","lead":"Dizayn chiroyli tugmalardan emas, balki foydalanuvchining ilova ichida adashmay, o'z maqsadiga erishishidan boshlanadi. Ushbu darsda foydalanuvchi hikoyasi (ssenariy) yozish, harakatlar xaritasi (User Flow) va hissiyotlar yo'li (CJM)ni loyihalashni o'rganamiz.","link":"/9-sinf/hafta-02/dars-1","slide":"/slaydlar/9-sinf/hafta-02/dars-1.html","test":"/slaydlar/9-sinf/hafta-02/dars-1-test.html"},{"g":5,"title":"Wireframe tushunchasi va Balsamiq dasturiga kirish","lead":"Uy qurishdan oldin uning chizmasi (cherteoj) chiziladi. Sayt va ilovalar yaratishda esa eng birinchi bo'lib Wireframe — interfeys skeleti loyihalanadi. Ushbu darsda nima uchun eng yaxshi dizaynlar oq-qora rangda boshlanishini va Balsamiq dasturida tezkor maketlar yasashni o'rganamiz.","link":"/9-sinf/hafta-02/dars-2","slide":"/slaydlar/9-sinf/hafta-02/dars-2.html","test":"/slaydlar/9-sinf/hafta-02/dars-2-test.html"},{"g":6,"title":"Balsamiq va Axure RP: asosiy UI komponentlar va dastlabki interfeys sxemalari","lead":"Birgina g'oya bor, lekin uni millionlab foydalanuvchilar tushunadigan interfeysga qanday aylantirish mumkin? Ushbu darsda professional Axure RP va Balsamiq vositalarida murakkab bloklar, sahifalar navigatsiyasi, kulranglar ierarxiyasi va wireframelarni Figmaga tayyorlashni o'rganamiz.","link":"/9-sinf/hafta-02/dars-3","slide":"/slaydlar/9-sinf/hafta-02/dars-3.html","test":"/slaydlar/9-sinf/hafta-02/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"9-sinf/hafta-02/index.md","filePath":"9-sinf/hafta-02/index.md"}`),h={name:"9-sinf/hafta-02/index.md"},m={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function g(y,a,f,q,c,k){const s=n("Icon");return l(),o("div",null,[i("div",m,[i("h2",u,[e(s,{name:"house"}),a[0]||(a[0]=t(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Natijalarni daftarda yoki bitta hujjatda (Google Docs, Notes, Balsamiq, Figma/Canva) saqlang; skrinshot va chizmalarni shu hujjatga qo&#39;shing. Topshirish: keyingi dars boshida mentorga ko&#39;rsating.</p><h3 id="_4-dars-uchun-ssenariy-user-flow-va-cjm" tabindex="-1">4-dars uchun (Ssenariy, User Flow va CJM) <a class="header-anchor" href="#_4-dars-uchun-ssenariy-user-flow-va-cjm" aria-label="Permalink to &quot;4-dars uchun (Ssenariy, User Flow va CJM)&quot;">​</a></h3><p><strong>1-topshiriq: «Mening ilovamdagi ssenariy va User Flow»</strong> (20–25 daqiqa)</p><ol><li>3-darsda tayyorlagan personangizni (yoki yangi personani) oling.</li><li>Uning ilovadagi bitta aniq vazifani (masalan: kitob yuklab olish yoki ovqat buyurtma qilish) bajarish ssenariysini 4 ta savol asosida yozing (Kim? Qayerda/qachon? Nima maqsad? Qanday harakatlar?).</li><li>Ushbu ssenariy bo&#39;yicha kamida 5 ta ekran va 1 ta qaror qabul qilish rombi (Ha/Yo&#39;q) qatnashgan User Flow blok-sxemasini chizing (daftarda yoki onlayn doskada).</li><li>Oqimda foydalanuvchi adashishi mumkin bo&#39;lgan 1 ta og&#39;riq nuqtasini belgilang va unga dizayn yechimini 1 jumlada taklif qiling.</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;liq yozilgan ssenariy matni, rombli User Flow chizmasi va bitta og&#39;riq nuqtasi yechimi. <strong>Nimani topshirasiz:</strong> daftardagi chizma rasmi yoki FigJam/Miro skrinshoti.</p><h3 id="_5-dars-uchun-wireframe-tushunchasi-va-balsamiq" tabindex="-1">5-dars uchun (Wireframe tushunchasi va Balsamiq) <a class="header-anchor" href="#_5-dars-uchun-wireframe-tushunchasi-va-balsamiq" aria-label="Permalink to &quot;5-dars uchun (Wireframe tushunchasi va Balsamiq)&quot;">​</a></h3><p><strong>2-topshiriq: «Low-fi qog&#39;oz eskizdan Balsamiqqa»</strong> (20–30 daqiqa)</p><ol><li>4-darsdagi User Flow&#39;ning asosiy 1 ta ekrani (masalan, Bosh sahifa yoki Mahsulot kartasi) uchun daftarga qalamda oddiy eskiz chizing.</li><li>Rasmlar o&#39;rniga &quot;X&quot; belgisi (Image placeholder) qo&#39;ying, tugma va sarlavhalarni joylang.</li><li>So&#39;ngra Balsamiq dasturida (balsamiq.cloud demo yoki desktop) xuddi shu ekranni raqamli wireframe qilib tering.</li><li>Quick Add orqali kamida 4 xil element (Button, Heading, Image, TextInput) qo&#39;shing.</li><li>Tayyor wireframeni PNG yoki PDF formatida eksport qiling.</li></ol><p><strong>Kutiladigan natija:</strong> daftardagi dastlabki eskiz va Balsamiqdan eksport qilingan raqamli wireframe tasviri. <strong>Nimani topshirasiz:</strong> qog&#39;oz eskiz fotosurati va Balsamiq PNG fayli.</p><h3 id="_6-dars-uchun-balsamiq-va-axure-rp-interfeys-sxemalari" tabindex="-1">6-dars uchun (Balsamiq va Axure RP interfeys sxemalari) <a class="header-anchor" href="#_6-dars-uchun-balsamiq-va-axure-rp-interfeys-sxemalari" aria-label="Permalink to &quot;6-dars uchun (Balsamiq va Axure RP interfeys sxemalari)&quot;">​</a></h3><p><strong>3-topshiriq: «Home_books to&#39;liq veb-wireframe&#39;i va Grayscale»</strong> (20–30 daqiqa)</p><ol><li>Axure RP (yoki Balsamiq/Figma)da veb-sahifa bosh ekrani wireframe&#39;ini yarating.</li><li>Sahifani <code>Home_books</code> deb nomlang.</li><li>Sahifaga Header (Logo, Menyu, Kirish tugmasi), Katta Banner, 3 ta kitob kartasi (Grid) va Footer bloklarini joylashtiring.</li><li>Kulranglar ierarxiyasini (Grayscale) to&#39;g&#39;ri qo&#39;llang: fon och kulrang, kartalar oq, asosiy sarlavha va tugmalar to&#39;q kulrang bo&#39;lsin.</li><li>Tayyor loyihani <code>home_books_wireframe.png</code> sifatida eksport qiling.</li></ol><p><strong>Kutiladigan natija:</strong> proporsiyalari toza, kulranglar ierarxiyasiga ega bo&#39;lgan to&#39;liq veb-sahifa wireframe&#39;i. <strong>Nimani topshirasiz:</strong> eksport qilingan PNG tasvir fayli.</p>',13))])])}const p=r(h,[["render",g]]);export{v as __pageData,p as default};
